// 78. Subsets
// https://leetcode.com/problems/subsets/description/
// Medium

// Approach: Recursion
// The overall time complexity is calculated by multiplying the total number of subsets generated by the work performed to copy each subset into the output list.
// the work performed to copy each subset into the output list = O(N)
// the total number of subsets generated = O(2^N)
// so, TC => O(N * 2^N)
// Space Complexity => O(N^2)
// Creating a new array instance at every recursive call forces memory allocations along the call stack, leading to O(N^2) auxiliary space in the worst-case stack frame chain.
class Solution1 {
    private func solve(_ nums: [Int], _ i: Int, _ currSubset: [Int], _ ans: inout [[Int]]) {
        // Base Case
        if i == nums.count {
            ans.append(currSubset)
            return 
        }

        // Recursive Cases

        // Case 1: exclude nums[i]
        solve(nums, i + 1, currSubset, &ans)

        // Case 2: include nums[i]
        var currSubset = currSubset // Creating a new array instance at every recursive cal
        currSubset.append(nums[i])
        solve(nums, i + 1, currSubset, &ans)
    }

    func subsets(_ nums: [Int]) -> [[Int]] {
        var ans = [[Int]]() 
        solve(nums, 0, [], &ans)
        return ans
    }
}

// Approach: Recursion
// Optimized Space Complexity
// The overall time complexity is calculated by multiplying the total number of subsets generated by the work performed to copy each subset into the output list.
// the work performed to copy each subset into the output list = O(N)
// the total number of subsets generated = O(2^N)
// so, TC => O(N * 2^N)
// Space Complexity => O(N) , recursion stack space
class Solution {
    private func solve(_ nums: [Int], _ i: Int, _ currSubset: inout [Int], _ ans: inout [[Int]]) {
        // Base Case
        if i == nums.count {
            ans.append(currSubset)
            return 
        }

        // Recursive Cases

        // Case 1: exclude nums[i]
        solve(nums, i + 1, &currSubset, &ans)

        // Case 2: include nums[i]
        currSubset.append(nums[i])
        solve(nums, i + 1, &currSubset, &ans)
        currSubset.removeLast() // Backtrack (restores state in O(1))
    }

    func subsets(_ nums: [Int]) -> [[Int]] {
        var ans = [[Int]]() 
        var currSubset = [Int]()
        solve(nums, 0, &currSubset, &ans)
        return ans
    }
}

